from functools import lru_cache
import sys
sys.setrecursionlimit(10000)
def T0(n):
    E=[(i,j) for i in range(n) for j in range(i+1,n)]
    adj=[[] for _ in range(n)]
    for k,(i,j) in enumerate(E):
        adj[i].append((j,k));adj[j].append((i,k))
    full=(1<<len(E))-1
    @lru_cache(maxsize=None)
    def f(v,used):
        if used==full: return 1
        t=0
        for w,k in adj[v]:
            if not (used>>k)&1: t+=f(w,used|(1<<k))
        return t
    return f(0,0),len(E)
for n,ref in [(5,264),(7,129976320)]:
    t,m=T0(n)
    oriented_lines=n*t
    U=oriented_lines//(2*m)
    print('K%d: trails from 0 =%d, oriented lines=%d, lines up to reversal=%d, unoriented circuits=%d'%(n,t,oriented_lines,oriented_lines//2,U))
    print('PASS' if U==ref else 'FAIL (U=%d vs %d)'%(U,ref))
